class CheckpointTests(unittest.TestCase):
    def test_only_explicit_local_checkpoint_with_matching_hash_is_accepted(
        self,
    ):
        with tempfile.TemporaryDirectory() as directory:
            path = Path(directory) / "model.ckpt"
            path.write_bytes(b"checkpoint bytes")
            digest = hashlib.sha256(path.read_bytes()).hexdigest()
            self.assertEqual(path, worker.verify_checkpoint(path, digest))
            with self.assertRaises(ValueError):
                worker.verify_checkpoint(path, "0" * 64)
            with self.assertRaises(ValueError):
                worker.verify_checkpoint(path, "not a checksum")
        with self.assertRaises(ValueError):
            worker.verify_checkpoint(
                "https://example.invalid/model.ckpt", "0" * 64
            )

    def test_invalid_model_timestamps_are_rejected(self):
        for invalid in [
            [float("nan")],
            [float("inf")],
            [-0.1],
            [2.1],
            [0.5, 0.4],
            [0.5, 0.5],
        ]:
            with self.subTest(invalid=invalid), self.assertRaises(ValueError):
                worker.validate_positions(invalid, 2.0)
        self.assertEqual([0.0, 0.5], worker.validate_positions([0, 0.5], 2.0))
        self.assertEqual(
            [0.0, 0.5], worker.validate_positions([0, 0.5, 2.0, 2.02], 2.0)
        )


